preConditionHook:
// WILDER'S PARABOLIC SAR, LITERALLY, USED AS AN EXIT-ONLY TRAILING STOP --
// Grimes's archetype of a stop that accelerates on its own schedule:
//     sar = sar + af * (ep - sar)
// with af starting at afStart and stepping by afStep to afMax every time the
// position prints a new extreme point.
//
// NEVER STOP-AND-REVERSE. Wilder's SAR flips side when hit; this is an exit,
// the generator's own MarketPosition guard decides which side is live, so the
// recursion is carried once in the position's direction and restarts at the
// next entry.
//
// ALL STATE IS PER POSITION and resets on ctx.BarsSinceEntry() == 0 -- VERIFIED
// as 0 on the fill bar and as restarting through a REVERSAL, which opens a
// position without ever passing through flat and which a MarketPosition() == 0
// reset would miss (BreakevenStopAfterEmaHoldingRun's idiom). While flat the
// reset repeats and neither condition can fire.
//
// THE SEED: on the fill bar the extreme point is that bar's own extreme and the
// stop the opposite extreme -- there is no pre-entry trend to inherit. The stop
// is not live on the fill bar (BarsSinceEntry >= 1 in both conditions): one bar
// of ratcheting must happen first, or a fill bar closing on its low would be
// stopped out on the spot.
//
// WILDER'S CLAMP: the SAR may never sit inside the PRIOR TWO BARS' range, so
// after the ratchet it is pulled back to low[1] / low[2] on a long and to
// high[1] / high[2] on a short. Real price bars, so no mirroring, no warm-up.
//
// ORDER OF OPERATIONS is Wilder's: advance the stop from the previous bar's af
// and extreme point, clamp, and only afterwards let this bar's extreme update
// the extreme point and the acceleration factor. The cap is an if, not MinList,
// so both twins read as the same walk.
//
// ParabolicAccelerationExit shares only the name -- it compares two successive
// leg magnitudes and carries no recursion. Re-read against its JSON.
//
// Everything is a price plus a multiple of a price DIFFERENCE, so the whole
// recursion shifts with the series and passes the shift test.
//
// All state is in localVariables, never at hook scope, so the rule survives
// double placement.
if (ctx.BarsSinceEntry() == 0) {
    af = afStart;
    ep = close[0];
    sar = close[0];
    if (el_gt(ctx.MarketPosition(), 0)) {
        ep = high[0];
        sar = low[0];
    }
    if (el_lt(ctx.MarketPosition(), 0)) {
        ep = low[0];
        sar = high[0];
    }
} else {
    sar = sar + af * (ep - sar);
    if (el_gt(ctx.MarketPosition(), 0)) {
        if (el_gt(sar, low[1])) {
            sar = low[1];
        }
        if (el_gt(sar, low[2])) {
            sar = low[2];
        }
        if (el_gt(high[0], ep)) {
            ep = high[0];
            af = af + afStep;
            if (el_gt(af, afMax)) {
                af = afMax;
            }
        }
    }
    if (el_lt(ctx.MarketPosition(), 0)) {
        if (el_lt(sar, high[1])) {
            sar = high[1];
        }
        if (el_lt(sar, high[2])) {
            sar = high[2];
        }
        if (el_lt(low[0], ep)) {
            ep = low[0];
            af = af + afStep;
            if (el_gt(af, afMax)) {
                af = afMax;
            }
        }
    }
}
